import AppKit

/// The practice project (spec §11 TU-6, TU-7): a small `.framejob` package in
/// the bundle (`Contents/Resources/Practice Project.framejob`), made by
/// `tools/practice/` and opened as an UNTITLED copy, so the bundled package
/// is never written and a save asks where.
///
/// Its `project.json` names each media at a placeholder path that never
/// resolves; the open path's own read re-anchors every one at the package's
/// `media/` (`ProjectDocument.repairingMedia`), so the copy plays the
/// bundle's files, read-only. Help ▸ Tutorials ▸ Open Practice Project
/// (`AppDelegate+Tutorials.swift`) and `new_project {practice: true}`
/// (`AgentServer+Project.swift`) both open it through `open()`.
///
/// **A saved copy owns its media.** The save funnel
/// (`ProjectDocument+CacheSaves.swift`) notes where each save is going, and
/// `ProjectDocument+PracticeMedia.swift`'s `write(to:…)` copies the bundled
/// files the copy uses into the package it writes and points `project.json`
/// at them there. `bundledMedia(in:)`, `packageName(for:in:)` and the
/// destination record are its helpers; `MediaConsolidator` asks
/// `bundledURL` so Consolidate relinks a file already carried rather than
/// copying it again.
///
/// **An open of anything inside the app is never in place**:
/// `ProjectDocumentController` sends such a URL here, and `open_project`
/// refuses it (`isInsideApp`).
enum PracticeProject {
    static let displayName = "Practice Project"
    static let resourceName = "Practice Project"
    static let resourceExtension = "framejob"

    /// The bundled package, or nil when this build holds none.
    static var bundledURL: URL? {
        Bundle.main.url(forResource: resourceName, withExtension: resourceExtension)
    }

    /// `url` (symlinks resolved, standardized) is `Bundle.main.bundleURL` or under it.
    static func isInsideApp(_ url: URL) -> Bool {
        let app = Bundle.main.bundleURL.resolvingSymlinksInPath().standardizedFileURL.path
        let path = url.resolvingSymlinksInPath().standardizedFileURL.path
        return path == app || path.hasPrefix(app.hasSuffix("/") ? app : app + "/")
    }

    /// Media of `snapshot` whose `path` (standardized) lies in `bundledURL/media/` and whose
    /// file exists there: id → that file.
    static func bundledMedia(in snapshot: ProjectSnapshot) -> [UInt32: URL] {
        guard let package = bundledURL else { return [:] }
        let folder = package.appendingPathComponent("media", isDirectory: true)
            .standardizedFileURL.path
        var found: [UInt32: URL] = [:]
        for media in snapshot.media where !media.path.isEmpty {
            let url = URL(fileURLWithPath: media.path).standardizedFileURL
            guard url.deletingLastPathComponent().path == folder,
                  FileManager.default.fileExists(atPath: url.path)
            else { continue }
            found[media.id] = url
        }
        return found
    }

    /// The name `source` takes in `folder`: its own file name, or, when that name holds a file
    /// of another byte size, the first `<stem>-<n>.<ext>` (n ≥ 2) that is absent or of the same
    /// size. Stable across writes: a file carried from the last save keeps its name.
    static func packageName(for source: URL, in folder: URL) -> String {
        let name = source.lastPathComponent
        let size = byteSize(source)
        func fits(_ candidate: String) -> Bool {
            let url = folder.appendingPathComponent(candidate)
            guard FileManager.default.fileExists(atPath: url.path) else { return true }
            return byteSize(url) == size
        }
        if fits(name) { return name }
        let stem = (name as NSString).deletingPathExtension
        let ext = (name as NSString).pathExtension
        var suffix = 2
        while true {
            let candidate = ext.isEmpty ? "\(stem)-\(suffix)" : "\(stem)-\(suffix).\(ext)"
            if fits(candidate) { return candidate }
            suffix += 1
        }
    }

    private static func byteSize(_ url: URL) -> Int? {
        (try? url.resourceValues(forKeys: [.fileSizeKey]))?.fileSize
    }

    // MARK: - Where a save is going

    /// Each document's save in flight, by `ObjectIdentifier(document)`. Main only.
    private static var destinations: [ObjectIdentifier: URL] = [:]

    /// The save funnel's record of where a save is going. Main only.
    static func noteDestination(_ url: URL, for document: ProjectDocument) {
        assert(Thread.isMainThread)
        destinations[ObjectIdentifier(document)] = url
    }

    static func clearDestination(for document: ProjectDocument) {
        assert(Thread.isMainThread)
        destinations[ObjectIdentifier(document)] = nil
    }

    static func destination(for document: ProjectDocument) -> URL? {
        destinations[ObjectIdentifier(document)]
    }

    // MARK: - Opening

    /// `document.read(from: package, ofType: ProjectDocument.projectTypeIdentifier)` — the open
    /// path's own read, so `repairingMedia` re-anchors every media at the package's `media/`;
    /// then throws naming each file still in `document.missingMedia`.
    static func read(into document: ProjectDocument, from package: URL) throws {
        try document.read(from: package, ofType: ProjectDocument.projectTypeIdentifier)
        let missing = document.missingMedia.map { ($0.path as NSString).lastPathComponent }
        guard missing.isEmpty else {
            throw ReelCoreError(
                message: "The practice project's media did not open from "
                    + "\(package.lastPathComponent): \(missing.joined(separator: ", ")).")
        }
    }

    /// Opens a copy of the bundled package as an untitled document, shown in a window. Main
    /// only. The order follows `ProjectDocument.untitled(around:)` but for its import count,
    /// so the copy opens clean: 1 `openUntitledDocumentAndDisplay(false)`; 2 the title,
    /// before anything reads `displayName`; 3 `read(into:from:)` (no bundled package is a
    /// `ReelCoreError`), and a throw after 1 closes the document; 4 `makeWindowControllers()`;
    /// 5 `showWindows()`. It never sets `fileURL`, so the bundle is never the autosave
    /// location and a save asks where.
    @discardableResult
    static func open() throws -> ProjectDocument {
        assert(Thread.isMainThread)
        guard let document = try NSDocumentController.shared.openUntitledDocumentAndDisplay(false)
            as? ProjectDocument
        else {
            throw ReelCoreError(
                message: "The untitled document did not open as a Frame Job project.")
        }
        document.displayName = displayName
        do {
            guard let package = bundledURL else {
                throw ReelCoreError(message: "This copy of Frame Job holds no practice project.")
            }
            try read(into: document, from: package)
        } catch {
            document.close()
            throw error
        }
        document.makeWindowControllers()
        document.showWindows()
        return document
    }
}

