// Tutorials TU1b — one scene movie of the practice project (spec §11 TU-7).
//
// Compiled beside `practice_generator.swift` (as `main.swift`) over
// `app/Sources` by `tools/practice/make_practice.py`, through
// `tools/proof/swift_build.py`'s `build()`. Everything here is drawn and
// synthesized: AVFoundation's H.264 and AAC encoders, Core Graphics for the
// picture, Core Text with the two OFL fonts already in `app/Resources/Fonts`
// (Montserrat ExtraBold, IBM Plex Mono Medium), and sine tones for the sound.
// No footage, no recording, no music, nothing resembling a person, logo or
// brand.
//
// A scene is 8 s of 1280×720 at 30 fps, H.264 at an average 800 kb/s with
// BT.709 tags, and 48 kHz stereo AAC at 128 kb/s: a sustained triad that
// swells once a second between 0.7 and 1.0 of its level, peaking at or under
// −14 dBFS, with 50 ms fades at the file's two ends. The picture shows the
// scene's number and name top left and its own source time `SS:FF` bottom
// right, so a viewer can tell the three scenes, and a slip or trim, apart.
import AVFoundation
import CoreGraphics
import CoreText
import Foundation

struct PracticeScene {
    enum Look { case dawn, sea, night }

    let number: Int
    let name: String
    let look: Look
    /// The triad's three frequencies, in Hz.
    let triad: [Double]

    var fileName: String { "\(name).mov" }
    var label: String { "\(number) \(name)" }

    static let all = [
        PracticeScene(number: 1, name: "Dawn", look: .dawn, triad: [261.63, 329.63, 392.00]),
        PracticeScene(number: 2, name: "Sea", look: .sea, triad: [349.23, 440.00, 523.25]),
        PracticeScene(number: 3, name: "Night", look: .night, triad: [196.00, 246.94, 293.66]),
    ]
}

struct PracticeMovieError: Error, CustomStringConvertible {
    let description: String
}

enum PracticeMovie {
    static let width = 1280
    static let height = 720
    static let fps: Int32 = 30
    static let seconds = 8
    static let sampleRate = 48_000
    /// Each sine's amplitude: three of them at the swell's top peak at 0.18, −14.9 dBFS.
    static let toneLevel = 0.06
    static let fadeSeconds = 0.05

    static func write(_ scene: PracticeScene, to url: URL, fonts: URL) throws {
        try? FileManager.default.removeItem(at: url)
        let titleFont = try font(fonts.appendingPathComponent("Montserrat-ExtraBold.ttf"), 64)
        let timeFont = try font(fonts.appendingPathComponent("IBMPlexMono-Medium.ttf"), 34)
        let writer = try AVAssetWriter(outputURL: url, fileType: .mov)
        let video = AVAssetWriterInput(mediaType: .video, outputSettings: [
            AVVideoCodecKey: AVVideoCodecType.h264,
            AVVideoWidthKey: width,
            AVVideoHeightKey: height,
            AVVideoCompressionPropertiesKey: [
                AVVideoAverageBitRateKey: 800_000,
                AVVideoExpectedSourceFrameRateKey: Int(fps),
                AVVideoMaxKeyFrameIntervalKey: Int(fps),
                AVVideoProfileLevelKey: AVVideoProfileLevelH264HighAutoLevel,
            ],
            AVVideoColorPropertiesKey: [
                AVVideoColorPrimariesKey: AVVideoColorPrimaries_ITU_R_709_2,
                AVVideoTransferFunctionKey: AVVideoTransferFunction_ITU_R_709_2,
                AVVideoYCbCrMatrixKey: AVVideoYCbCrMatrix_ITU_R_709_2,
            ],
        ])
        video.expectsMediaDataInRealTime = false
        let adaptor = AVAssetWriterInputPixelBufferAdaptor(
            assetWriterInput: video,
            sourcePixelBufferAttributes: [
                kCVPixelBufferPixelFormatTypeKey as String: REDACTED,
                kCVPixelBufferWidthKey as String: width,
                kCVPixelBufferHeightKey as String: height,
            ])
        let audio = AVAssetWriterInput(mediaType: .audio, outputSettings: [
            AVFormatIDKey: kAudioFormatMPEG4AAC,
            AVSampleRateKey: sampleRate,
            AVNumberOfChannelsKey: 2,
            AVEncoderBitRateKey: 128_000,
        ])
        audio.expectsMediaDataInRealTime = false
        guard writer.canAdd(video), writer.canAdd(audio) else {
            throw PracticeMovieError(description: "the writer refused an input for \(url.path)")
        }
        writer.add(video)
        writer.add(audio)
        guard writer.startWriting() else {
            throw PracticeMovieError(
                description: "startWriting: \(writer.error.map { "\($0)" } ?? "no error")")
        }
        writer.startSession(atSourceTime: .zero)
        let format = try audioFormat()
        let samples = tone(scene)
        let frames = seconds * Int(fps)
        let chunk = sampleRate / Int(fps)  // one picture frame's worth of sound
        for frame in 0..<frames {
            let time = CMTime(value: CMTimeValue(frame), timescale: fps)
            try wait(for: video, writer)
            guard let pool = adaptor.pixelBufferPool else {
                throw PracticeMovieError(description: "the adaptor has no pixel buffer pool")
            }
            let buffer = try draw(scene, frame: frame, pool: pool, title: titleFont,
                                  time: timeFont)
            guard adaptor.append(buffer, withPresentationTime: time) else {
                throw PracticeMovieError(description: "video append at frame \(frame): "
                                         + "\(writer.error.map { "\($0)" } ?? "no error")")
            }
            try wait(for: audio, writer)
            let first = frame * chunk
            let sound = try audioBuffer(samples, from: first, count: chunk, format: format)
            guard audio.append(sound) else {
                throw PracticeMovieError(description: "audio append at frame \(frame): "
                                         + "\(writer.error.map { "\($0)" } ?? "no error")")
            }
        }
        video.markAsFinished()
        audio.markAsFinished()
        let done = DispatchSemaphore(value: 0)
        writer.finishWriting { done.signal() }
        guard done.wait(timeout: .now() + 60) == .success, writer.status == .completed else {
            throw PracticeMovieError(description: "finishWriting: status \(writer.status.rawValue) "
                                     + "\(writer.error.map { "\($0)" } ?? "")")
        }
    }

    private static func wait(for input: AVAssetWriterInput, _ writer: AVAssetWriter) throws {
        let deadline = Date().addingTimeInterval(30)
        while !input.isReadyForMoreMediaData {
            if writer.status == .failed || Date() > deadline {
                throw PracticeMovieError(description: "the writer stopped taking data: "
                                         + "\(writer.error.map { "\($0)" } ?? "timed out")")
            }
            Thread.sleep(forTimeInterval: 0.002)
        }
    }

    private static func font(_ url: URL, _ size: CGFloat) throws -> CTFont {
        guard let descriptors = CTFontManagerCreateFontDescriptorsFromURL(url as CFURL)
                as? [CTFontDescriptor], let descriptor = descriptors.first
        else { throw PracticeMovieError(description: "no font in \(url.path)") }
        return CTFontCreateWithFontDescriptor(descriptor, size, nil)
    }

    // MARK: - The picture

    private static func rgb(_ r: CGFloat, _ g: CGFloat, _ b: CGFloat, _ a: CGFloat = 1)
        -> CGColor
    {
        CGColor(red: r / 255, green: g / 255, blue: b / 255, alpha: a)
    }

    private static func draw(
        _ scene: PracticeScene, frame: Int, pool: CVPixelBufferPool, title: CTFont, time: CTFont
    ) throws -> CVPixelBuffer {
        var made: CVPixelBuffer?
        guard CVPixelBufferPoolCreatePixelBuffer(nil, pool, &made) == kCVReturnSuccess,
              let buffer = made
        else { throw PracticeMovieError(description: "no pixel buffer at frame \(frame)") }
        CVPixelBufferLockBaseAddress(buffer, [])
        defer { CVPixelBufferUnlockBaseAddress(buffer, []) }
        guard let space = CGColorSpace(name: CGColorSpace.itur_709),
              let context = CGContext(
                data: CVPixelBufferGetBaseAddress(buffer), width: width, height: height,
                bitsPerComponent: 8, bytesPerRow: CVPixelBufferGetBytesPerRow(buffer),
                space: space,
                bitmapInfo: CGImageAlphaInfo.premultipliedFirst.rawValue
                    | CGBitmapInfo.byteOrder32Little.rawValue)
        else { throw PracticeMovieError(description: "no bitmap context at frame \(frame)") }
        let t = Double(frame) / Double(fps)
        switch scene.look {
        case .dawn: dawn(context, t)
        case .sea: sea(context, t)
        case .night: night(context, t)
        }
        context.saveGState()
        context.setShadow(offset: CGSize(width: 0, height: -3), blur: 12,
                          color: rgb(0, 0, 0, 0.45))
        text(scene.label, title, at: CGPoint(x: 72, y: CGFloat(height) - 72 - 64), context)
        let stamp = String(format: "%02d:%02d", frame / Int(fps), frame % Int(fps))
        let line = CTLineCreateWithAttributedString(attributed(stamp, time))
        let wide = CTLineGetTypographicBounds(line, nil, nil, nil)
        text(stamp, time, at: CGPoint(x: CGFloat(width) - 64 - CGFloat(wide), y: 52), context)
        context.restoreGState()
        return buffer
    }

    private static func attributed(_ string: String, _ font: CTFont) -> CFAttributedString {
        let attributes: [CFString: Any] = [
            kCTFontAttributeName: font,
            kCTForegroundColorAttributeName: rgb(255, 255, 255),
        ]
        return CFAttributedStringCreate(nil, string as CFString, attributes as CFDictionary)
    }

    private static func text(_ string: String, _ font: CTFont, at point: CGPoint,
                             _ context: CGContext)
    {
        let line = CTLineCreateWithAttributedString(attributed(string, font))
        context.textPosition = point
        CTLineDraw(line, context)
    }

    private static func gradient(_ context: CGContext, top: CGColor, bottom: CGColor) {
        guard let gradient = CGGradient(
            colorsSpace: context.colorSpace, colors: [bottom, top] as CFArray,
            locations: [0, 1])
        else { return }
        context.drawLinearGradient(
            gradient, start: .zero, end: CGPoint(x: 0, y: height), options: [])
    }

    /// Peach to rose, a pale sun rising from behind the lower edge.
    private static func dawn(_ context: CGContext, _ t: Double) {
        gradient(context, top: rgb(255, 196, 160), bottom: rgb(214, 104, 132))
        let rise = CGFloat(t / Double(seconds))
        let center = CGPoint(x: 820, y: 120 + 300 * rise)
        context.setFillColor(rgb(255, 244, 214, 0.25))
        context.fillEllipse(in: CGRect(x: center.x - 150, y: center.y - 150, width: 300,
                                       height: 300))
        context.setFillColor(rgb(255, 246, 224, 0.95))
        context.fillEllipse(in: CGRect(x: center.x - 100, y: center.y - 100, width: 200,
                                       height: 200))
        context.setFillColor(rgb(176, 84, 120, 0.55))
        context.fill(CGRect(x: 0, y: 0, width: width, height: 90))
    }

    /// Teal to navy, three translucent wave bands drifting at their own speeds.
    private static func sea(_ context: CGContext, _ t: Double) {
        gradient(context, top: rgb(72, 176, 178), bottom: rgb(18, 40, 92))
        let bands: [(base: Double, amplitude: Double, length: Double, speed: Double, alpha: CGFloat)]
            = [(420, 26, 520, 40, 0.18), (300, 34, 380, -60, 0.22), (170, 22, 300, 90, 0.28)]
        for band in bands {
            let path = CGMutablePath()
            path.move(to: CGPoint(x: 0, y: 0))
            for x in stride(from: 0, through: width, by: 8) {
                let phase = (Double(x) + band.speed * t) / band.length * 2 * .pi
                path.addLine(to: CGPoint(x: Double(x), y: band.base + band.amplitude * sin(phase)))
            }
            path.addLine(to: CGPoint(x: width, y: 0))
            path.closeSubpath()
            context.addPath(path)
            context.setFillColor(rgb(214, 244, 240, band.alpha))
            context.fillPath()
        }
    }

    /// Indigo to black, a crescent and seeded stars that twinkle.
    private static func night(_ context: CGContext, _ t: Double) {
        gradient(context, top: rgb(44, 36, 104), bottom: rgb(4, 4, 12))
        var seed: UInt64 = 0x5EED_0F_5747
        func next() -> Double {
            seed = seed &* 6_364_136_223_846_793_005 &+ 1_442_695_040_888_963_407
            return Double(seed >> 11) / Double(1 << 53)
        }
        for _ in 0..<90 {
            let x = next() * Double(width)
            let y = 160 + next() * Double(height - 160)
            let size = 1.5 + next() * 2.5
            let rate = 0.4 + next() * 1.2
            let offset = next() * 2 * .pi
            let glow = 0.45 + 0.55 * (0.5 + 0.5 * sin(2 * .pi * rate * t + offset))
            context.setFillColor(rgb(250, 246, 220, CGFloat(glow)))
            context.fillEllipse(in: CGRect(x: x, y: y, width: size, height: size))
        }
        let moon = CGRect(x: 960, y: 470, width: 150, height: 150)
        context.saveGState()
        context.beginTransparencyLayer(auxiliaryInfo: nil)
        context.setFillColor(rgb(250, 240, 200))
        context.fillEllipse(in: moon)
        context.setBlendMode(.clear)
        context.fillEllipse(in: moon.offsetBy(dx: 46, dy: 22))
        context.endTransparencyLayer()
        context.restoreGState()
    }

    // MARK: - The sound

    /// The whole scene's samples, interleaved stereo Float32.
    private static func tone(_ scene: PracticeScene) -> [Float] {
        let count = seconds * sampleRate
        let fade = Int(fadeSeconds * Double(sampleRate))
        var out = [Float](repeating: 0, count: count * 2)
        for index in 0..<count {
            let t = Double(index) / Double(sampleRate)
            let swell = 0.85 + 0.15 * sin(2 * .pi * t)
            var value = 0.0
            for frequency in scene.triad { value += sin(2 * .pi * frequency * t) }
            var edge = 1.0
            if index < fade { edge = Double(index) / Double(fade) }
            if index >= count - fade { edge = Double(count - 1 - index) / Double(fade) }
            let sample = Float(value * toneLevel * swell * edge)
            out[index * 2] = sample
            out[index * 2 + 1] = sample
        }
        return out
    }

    private static func audioFormat() throws -> CMAudioFormatDescription {
        var description = AudioStreamBasicDescription(
            mSampleRate: Float64(sampleRate), mFormatID: kAudioFormatLinearPCM,
            mFormatFlags: kAudioFormatFlagIsFloat | kAudioFormatFlagIsPacked,
            mBytesPerPacket: 8, mFramesPerPacket: 1, mBytesPerFrame: 8, mChannelsPerFrame: 2,
            mBitsPerChannel: 32, mReserved: 0)
        var format: CMAudioFormatDescription?
        let status = CMAudioFormatDescriptionCreate(
            allocator: nil, asbd: &description, layoutSize: 0, layout: nil, magicCookieSize: 0,
            magicCookie: nil, extensions: nil, formatDescriptionOut: &format)
        guard status == noErr, let format else {
            throw PracticeMovieError(description: "no audio format (\(status))")
        }
        return format
    }

    private static func audioBuffer(
        _ samples: [Float], from first: Int, count: Int, format: CMAudioFormatDescription
    ) throws -> CMSampleBuffer {
        let bytes = count * 8
        var block: CMBlockBuffer?
        var status = CMBlockBufferCreateWithMemoryBlock(
            allocator: nil, memoryBlock: nil, blockLength: bytes, blockAllocator: nil,
            customBlockSource: nil, offsetToData: 0, dataLength: bytes, flags: 0,
            blockBufferOut: &block)
        guard status == noErr, let block else {
            throw PracticeMovieError(description: "no audio block (\(status))")
        }
        status = samples.withUnsafeBufferPointer { pointer in
            CMBlockBufferReplaceDataBytes(
                with: pointer.baseAddress! + first * 2, blockBuffer: block, offsetIntoDestination: 0,
                dataLength: bytes)
        }
        guard status == noErr else {
            throw PracticeMovieError(description: "audio block fill (\(status))")
        }
        var sample: CMSampleBuffer?
        status = CMAudioSampleBufferCreateReadyWithPacketDescriptions(
            allocator: nil, dataBuffer: block, formatDescription: format, sampleCount: count,
            presentationTimeStamp: CMTime(value: CMTimeValue(first),
                                          timescale: CMTimeScale(sampleRate)),
            packetDescriptions: nil, sampleBufferOut: &sample)
        guard status == noErr, let sample else {
            throw PracticeMovieError(description: "no audio sample buffer (\(status))")
        }
        return sample
    }
}

