// Tutorials TU1b — the practice project's generator (spec §11 TU-7).
//
// Compiled AS `main.swift`, beside `practice_media.swift`, over every file in
// `app/Sources` but the app's own `main.swift`, through
// `tools/proof/swift_build.py`'s `build()` by `tools/practice/make_practice.py`.
//
//   practice_generator <out-package> <fonts-dir>
//
// Writes `<out-package>/media/{Dawn,Sea,Night}.mov` (`PracticeMovie.write`),
// probes each with the app's own `MediaImporter.probeBlocking`, replaces each
// descriptor's path with `/nonexistent/Practice Project.framejob/media/<file>`
// (a placeholder that never resolves: the app's open re-anchors it at the
// package's `media/`) and drops its bookmark, then builds the project through
// the core's own ops — `ReelProject.new(1280, 720, 30 fps)` and per scene in
// order `add_media`, `add_clip` at 0, 6 and 12 s on Track 1, `trim_end` to 6 s
// long and `slip` by +1 s, so each clip has a 1 s handle at both ends. It
// asserts three clips with no `transition_in`, and that a trial `add_transition`
// (cross dissolve, 0.5 s, center) applies before clips 2 and 3, then writes
// `<out-package>/project.json` from `ReelProject.json`.
//
// Prints one stdout line: `WROTE {json}`, or `FAILED <reason>` and exit 1.
import AVFoundation
import Foundation

func failed(_ reason: String) -> Never {
    print("FAILED \(reason)")
    fflush(stdout)
    exit(1)
}

let arguments = CommandLine.arguments
guard arguments.count == 3 else { failed("usage: practice_generator <out-package> <fonts-dir>") }
let package = URL(fileURLWithPath: arguments[1])
let fonts = URL(fileURLWithPath: arguments[2])
let mediaFolder = package.appendingPathComponent("media", isDirectory: true)
let placeholder = "/nonexistent/Practice Project.framejob/media/"
let second: Ticks = 600_000
let clipLength = 6 * second

do {
    try? FileManager.default.removeItem(at: package)
    try FileManager.default.createDirectory(at: mediaFolder, withIntermediateDirectories: true)
} catch {
    failed("the package folder could not be made: \(error)")
}

// MARK: - The media

var descriptors: [MediaDescriptor] = []
for scene in PracticeScene.all {
    let url = mediaFolder.appendingPathComponent(scene.fileName)
    do {
        try PracticeMovie.write(scene, to: url, fonts: fonts)
    } catch {
        failed("\(scene.fileName) was not written: \(error)")
    }
    var descriptor: MediaDescriptor
    do {
        descriptor = try MediaImporter.probeBlocking(url: url)
    } catch {
        failed("\(scene.fileName) did not probe: \(error)")
    }
    guard descriptor.hasVideo, descriptor.hasAudio, descriptor.width == PracticeMovie.width,
          descriptor.height == PracticeMovie.height,
          descriptor.duration >= Ticks(PracticeMovie.seconds) * second - second / 10
    else {
        failed("\(scene.fileName) probed as \(descriptor.width)×\(descriptor.height), "
               + "\(descriptor.duration) ticks, video \(descriptor.hasVideo), "
               + "audio \(descriptor.hasAudio)")
    }
    descriptor.path = placeholder + scene.fileName
    descriptor.bookmark = nil
    descriptors.append(descriptor)
}

// MARK: - The project, through the core

guard var project = ReelProject.new(width: PracticeMovie.width, height: PracticeMovie.height,
                                    fps: .thirty)
else { failed("ReelProject.new answered nil") }

func apply(_ op: ReelOp) {
    do {
        guard case .applied(let next) = try project.applying(op) else {
            failed("\(op.name) did not apply")
        }
        project = next
    } catch {
        failed("\(op.name): \(error)")
    }
}

guard let track = project.snapshot.tracks.first?.id else { failed("the new project has no track") }
var clipIDs: [UInt32] = []
for (index, descriptor) in descriptors.enumerated() {
    apply(.addMedia(descriptor: descriptor))
    guard let media = project.snapshot.media.last?.id else { failed("add_media added nothing") }
    let at = Ticks(index) * clipLength
    let before = Set(project.snapshot.clips.map(\.id))
    apply(.addClip(track: track, media: media, at: at))
    guard let clip = project.snapshot.clips.first(where: { !before.contains($0.id) })?.id else {
        failed("add_clip added nothing for \(descriptor.path)")
    }
    apply(.trimEnd(clip: clip, to: at + clipLength))
    apply(.slip(clip: clip, delta: second))
    clipIDs.append(clip)
}

let clips = project.snapshot.clips
guard clips.count == 3, clips.allSatisfy({ $0.track == track && $0.transitionIn == nil }) else {
    failed("the project holds \(clips.count) clips, or one has a transition or another track")
}
for (index, id) in clipIDs.enumerated() {
    guard let clip = clips.first(where: { $0.id == id }), clip.start == Ticks(index) * clipLength,
          clip.duration == clipLength, clip.source.sourceIn == second
    else { failed("clip \(id) is not a 6 s clip at \(index * 6) s with a 1 s head") }
}
for id in clipIDs.dropFirst() {
    let trial = try? project.applying(
        .addTransition(clip: id, kind: .crossDissolve, duration: second / 2, align: .center))
    guard let dissolved = trial?.project,
          dissolved.snapshot.clips.first(where: { $0.id == id })?.transitionIn != nil
    else { failed("a trial cross dissolve before clip \(id) did not apply") }
}

do {
    try Data(project.json.utf8).write(to: package.appendingPathComponent("project.json"),
                                      options: .atomic)
} catch {
    failed("project.json was not written: \(error)")
}

let report: [String: Any] = [
    "package": package.path,
    "media": descriptors.map { ($0.path as NSString).lastPathComponent },
    "clips": clipIDs.map(Int.init),
    "end_seconds": 3 * 6,
]
let data = (try? JSONSerialization.data(withJSONObject: report, options: [.sortedKeys])) ?? Data()
print("WROTE " + (String(data: data, encoding: .utf8) ?? "{}"))
fflush(stdout)
exit(0)

