private static func wait(for input: AVAssetWriterInput, _ writer: AVAssetWriter) throws {
    let deadline = Date().addingTimeInterval(30)
    while !input.isReadyForMoreMediaData {
        if writer.status == .failed || Date() > deadline {
            throw PracticeMovieError(description: "the writer stopped taking data: "
                                     + "\(writer.error.map { "\($0)" } ?? "timed out")")
        }
        Thread.sleep(forTimeInterval: 0.002)
    }
}

