            throw PracticeMovieError(description: "finishWriting: status \\(writer.status.rawValue) "
                                     + "\\(writer.error.map { "\\($0)" } ?? "")")
        }
    }

    /// What the two pumps share: the first failure, and each pump's one leave.
    private final class PumpState {
        private let lock = NSLock()
        private var first: String?
        private var left: Set<String> = []

        var failed: Bool { reason != nil }

        var reason: String? {
            lock.lock()
            defer { lock.unlock() }
            return first
        }

        func fail(_ reason: String) {
            lock.lock()
            if first == nil { first = reason }
            lock.unlock()
        }

        func leave(_ group: DispatchGroup, _ name: String) {
            lock.lock()
            let fresh = left.insert(name).inserted
            lock.unlock()
            if fresh { group.leave() }
        }
    }

