import AppKit

/// A saved practice copy owns its media (spec §11 TU-7).
///
/// A practice copy (`PracticeProject.open()`) plays the bundle's files in
/// place. Every write of it to a package — Save, Save As, an autosave in
/// place, `save_project {path}`, `new_project {practice: true, path}` — puts
/// the bundled files it uses into that package's `media/` and writes
/// `project.json` naming them at their place in the FINAL package, which the
/// save funnel noted (`ProjectDocument+CacheSaves.swift`,
/// `PracticeProject.noteDestination`). It all happens inside the one write
/// NSDocument makes to its temporary package, so a failure fails the save and
/// leaves the old package as it was.
///
/// What it does not do: change the open document — the copy keeps playing
/// the bundle's files until it is reopened, so its undo handles and the file
/// agree — or touch an autosave elsewhere (an untitled copy's autosave, which
/// a restore re-anchors only while the app has not moved), or a write with no
/// noted destination (File ▸ Duplicate's), or a project with no bundled media.
///
/// `ProjectDocument.swift` overrides `fileWrapper(ofType:)`, which writes
/// `project.json` and carries `media/`; this override runs after it.
extension ProjectDocument {
    override func write(
        to url: URL, ofType typeName: String, for saveOperation: NSDocument.SaveOperationType,
        originalContentsURL absoluteOriginalContentsURL: URL?
    ) throws {
        try super.write(
            to: url, ofType: typeName, for: saveOperation,
            originalContentsURL: absoluteOriginalContentsURL)
        guard saveOperation != .autosaveElsewhereOperation,
              let destination = PracticeProject.destination(for: self)
        else { return }
        let bundled = PracticeProject.bundledMedia(in: project.snapshot)
        guard !bundled.isEmpty else { return }
        let manager = FileManager.default
        let folder = url.appendingPathComponent("media", isDirectory: true)
        let finalFolder = destination.appendingPathComponent("media", isDirectory: true)
        try manager.createDirectory(at: folder, withIntermediateDirectories: true)
        var ops: [ReelOp] = []
        for (media, source) in bundled.sorted(by: { $0.key < $1.key }) {
            let name = PracticeProject.packageName(for: source, in: folder)
            let target = folder.appendingPathComponent(name)
            // A `media/` carried from the last save already holds it.
            if !manager.fileExists(atPath: target.path) {
                try manager.copyItem(at: source, to: target)
            }
            let path = finalFolder.appendingPathComponent(name).path
            ops.append(.relinkMedia(media: media, path: path))
        }
        switch try project.applying(ops) {
        case .applied(let relinked):
            guard let data = relinked.json.data(using: .utf8) else {
                throw ReelCoreError(message: "The practice project could not be encoded.")
            }
            try data.write(to: url.appendingPathComponent("project.json"), options: .atomic)
        case .identity:
            break
        case .refused(let refusal):
            throw ReelCoreError(message: refusal.reason)
        }
    }
}

import AppKit

/// Every save of the package announced to the cache ledger, so no marker,
/// waveform or voice file lands between the save's listing and its swap
/// (`MediaImporter.CacheLedger`, `MediaCacheLedger.swift`).
///
/// This one override is enough: ⌘S, Save As, autosave and `save_project`
/// all funnel through `save(to:ofType:for:completionHandler:)`, and NSDocument
/// lists the package for its lazy `cache/` wrapper and swaps the new package
/// in before that completion runs. `saveBegan` waits for a publication
/// already being written; `saveEnded` runs before the caller's handler.
///
/// The same funnel serves the practice project (spec §11 TU-7): it notes
/// where each save is going (`PracticeProject.noteDestination`) before
/// `super`, so `ProjectDocument+PracticeMedia.swift`'s `write(to:…)` can
/// name the media at their place in the FINAL package, and clears it in the
/// completion, before the caller's handler. A practice copy that now has a
/// file gives up its "Practice Project" title there, so the window, the
/// Window menu and every summary take the file's name.
extension ProjectDocument {
    override func save(
        to url: URL, ofType typeName: String, for saveOperation: NSDocument.SaveOperationType,
        completionHandler: @escaping ((any Error)?) -> Void
    ) {
        PracticeProject.noteDestination(url, for: self)
        guard let directory = intendedCacheDirectory else {
            super.save(to: url, ofType: typeName, for: saveOperation) { [weak self] error in
                self?.practiceSaveEnded(error)
                completionHandler(error)
            }
            return
        }
        let save = MediaImporter.CacheLedger.shared.saveBegan(cacheDir: directory)
        super.save(to: url, ofType: typeName, for: saveOperation) { [weak self] error in
            MediaImporter.CacheLedger.shared.saveEnded(cacheDir: directory, save: save)
            self?.practiceSaveEnded(error)
            completionHandler(error)
        }
    }

    /// The funnel's completion half for the practice project (spec §11 TU-7).
    private func practiceSaveEnded(_ error: (any Error)?) {
        PracticeProject.clearDestination(for: self)
        if error == nil, fileURL != nil, displayName == PracticeProject.displayName {
            displayName = nil
        }
    }
}

